// GENERATED by build/build-workflows.js from src/config.js, src/notify.js. Edit those files, not this node.

/**
 * Central settings for the Inspection → AI Quote → Approval → Pipedrive workflow.
 *
 * This is the ONLY file most changes should need. The build script copies it
 * into the "Config" Code node, and every other node reads settings from there.
 *
 * Secrets (API keys) never go here. They live in n8n Credentials.
 */
function getConfig() {
  return {
    // "mock" runs the whole flow with no API keys (good for demos and tests).
    // "live" calls the Anthropic API and Pipedrive for real.
    aiMode: 'mock',
    crmMode: 'mock',

    ai: {
      url: 'https://api.anthropic.com/v1/messages',
      model: 'claude-sonnet-5-5',
      maxTokens: 1500,
      // Below this the quote is still produced, but the approver is warned.
      minConfidence: 0.6,
    },

    crm: {
      // Use https://<your-company>.pipedrive.com/api/v1 or https://api.pipedrive.com/v1
      baseUrl: 'https://api.pipedrive.com/v1',
      currency: 'AUD',
    },

    notify: {
      // Where approval requests and alerts are POSTed.
      // Default is the bundled "Mock Inbox" workflow, so it works out of the box.
      url: 'http://localhost:5678/webhook/mock-inbox',
      // "generic" (Mock Inbox), "slack", "discord" or "googlechat"
      channel: 'generic',
    },

    serviceAreas: ['Melbourne', 'Sydney', 'Brisbane'],

    // Same request seen again within this window is ignored.
    dedupWindowHours: 72,

    approval: {
      // Quotes not approved within this window expire and alert the team.
      expiresAfterHours: 48,
    },

    pricing: {
      gstRate: 0.1,
      minimumCharge: 350, // ex GST, applied when the job total is below it
      // Quotes above this total (inc GST) get a "senior sign-off" warning.
      highValueThreshold: 10000,
    },

    // Placeholder rates (ex GST). Replace with real rates before going live.
    // The AI is only allowed to pick codes from this list; it never sets prices.
    catalog: {
      CONC_CRACK_REPAIR: { label: 'Concrete crack repair', unit: 'lm', rate: 45, maxQty: 500 },
      CONC_PATCH: { label: 'Concrete spall / patch repair', unit: 'm2', rate: 180, maxQty: 200 },
      TRIP_HAZARD_GRIND: { label: 'Trip hazard grinding', unit: 'each', rate: 95, maxQty: 100 },
      PAVER_RELAY: { label: 'Paver lift and relay', unit: 'm2', rate: 120, maxQty: 300 },
      TILE_REPLACE: { label: 'Tile replacement', unit: 'each', rate: 65, maxQty: 400 },
      JOINT_RESEAL: { label: 'Expansion joint reseal', unit: 'lm', rate: 22, maxQty: 1000 },
      PRESSURE_CLEAN: { label: 'Pressure clean', unit: 'm2', rate: 6, maxQty: 5000 },
      LINE_MARKING: { label: 'Line marking', unit: 'lm', rate: 8, maxQty: 2000 },
      SITE_INSPECTION: { label: 'Site inspection and report', unit: 'each', rate: 250, maxQty: 5 },
    },
  };
}

/**
 * Builds every message the workflow sends (approval requests, outcomes,
 * alerts) and formats it for the configured channel.
 */
function money(n, currency) {
  return (currency === 'AUD' ? 'A$' : '') + Number(n).toLocaleString('en-AU', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatForChannel(n, channel) {
  const linkText = (fmt) => (n.links || []).map(fmt).join('  |  ');
  const body = [n.title, '', ...(n.lines || [])].join('\n');
  switch (channel) {
    case 'slack':
    case 'googlechat':
      return { text: [body, linkText((l) => `<${l.url}|${l.label}>`)].filter(Boolean).join('\n\n') };
    case 'discord':
      return { content: [body, linkText((l) => `[${l.label}](${l.url})`)].filter(Boolean).join('\n\n').slice(0, 2000) };
    default:
      return { title: n.title, severity: n.severity || 'info', text: (n.lines || []).join('\n'), links: n.links || [], sentAt: new Date().toISOString() };
  }
}

function buildApprovalRequest({ request, scope, quote, warnings, resumeUrl, token, expiresAt }) {
  const c = quote.currency;
  const sep = resumeUrl.includes('?') ? '&' : '?';
  const link = (decision) => `${resumeUrl}${sep}decision=${decision}&token=${encodeURIComponent(token)}`;
  const lines = [
    `Customer: ${request.customer.name}${request.customer.company ? ' (' + request.customer.company + ')' : ''} <${request.customer.email}>`,
    `Site: ${request.property.address}, ${request.property.city}`,
    `AI summary: ${scope.summary || '-'} (confidence ${scope.confidence})`,
    '',
    ...quote.lines.map((l) => `- ${l.description}: ${l.quantity} ${l.unit} x ${money(l.rate, c)} = ${money(l.lineTotal, c)}`),
    '',
    `Subtotal ${money(quote.subtotal, c)} | GST ${money(quote.gst, c)} | Total ${money(quote.total, c)}`,
  ];
  if (quote.highValue) lines.push('', 'HIGH VALUE: needs senior sign-off.');
  if (warnings.length) lines.push('', 'Check before approving:', ...warnings.map((w) => `! ${w}`));
  if (scope.assumptions.length) lines.push('', 'AI assumptions:', ...scope.assumptions.map((a) => `? ${a}`));
  lines.push('', `Expires: ${expiresAt}`);

  return {
    title: `Quote ${request.ref} needs approval: ${money(quote.total, c)}`,
    severity: quote.highValue || warnings.length ? 'warning' : 'info',
    lines,
    links: [
      { label: 'Approve', url: link('approve') },
      { label: 'Reject', url: link('reject') },
    ],
  };
}

// ---- node glue ----
const config = getConfig();
const e = $input.first().json;
const exec = e.execution || {};
const message = {
  title: `Automation failed: ${(e.workflow && e.workflow.name) || 'unknown workflow'}`,
  severity: 'error',
  lines: [
    `Node: ${exec.lastNodeExecuted || 'unknown'}`,
    `Error: ${((exec.error && exec.error.message) || 'unknown').slice(0, 500)}`,
    `Mode: ${exec.mode || '-'}  Execution: ${exec.id || '-'}`,
  ],
  links: exec.url ? [{ label: 'Open execution', url: exec.url }] : [],
};
return [{ json: { notifyUrl: config.notify.url, payload: formatForChannel(message, config.notify.channel), message } }];
